# Update data.js
$dataPath = "js/data.js"
$content = Get-Content $dataPath -Raw -Encoding UTF8
$jsonStart = $content.IndexOf("[")
$jsonEnd = $content.LastIndexOf("]")
$jsonStr = $content.Substring($jsonStart, $jsonEnd - $jsonStart + 1)
$companies = $jsonStr | ConvertFrom-Json

foreach ($c in $companies) {
  if ($masterMaps.ContainsKey($c.id)) {
    $c.googleMapsUrl = $masterMaps[$c.id]
    $c.gmaps = $masterMaps[$c.id]
  }
}

$updatedJson = $companies | ConvertTo-Json -Depth 10
$updatedJson = $updatedJson -replace '\\u0026', '&'

$newContent = "var UDON_COMPANIES = " + $updatedJson + ";" + [Environment]::NewLine + [Environment]::NewLine + "if (typeof window !== 'undefined') {" + [Environment]::NewLine + "  window.UDON_COMPANIES = UDON_COMPANIES;" + [Environment]::NewLine + "}" + [Environment]::NewLine
[System.IO.File]::WriteAllText((Get-Item $dataPath).FullName, $newContent, [System.Text.Encoding]::UTF8)

Write-Host "Updated js/data.js successfully with 58 companies!"
